const books = [
 {title:'The Intelligent Investor',author:'Benjamin Graham',genre:'Finance',color:'#273c3b',height:310,width:53,mark:'VALUE',framework:true,description:'A patient, practical foundation for thinking about investing as ownership rather than speculation. Graham’s enduring approach centers on discipline, perspective, and a margin of safety.'},
 {title:'Money Works: The Guide to Financial Literacy',author:'Abhijeet Kolapkar',genre:'Finance',color:'#c46645',height:278,width:47,mark:'MONEY',accent:true,description:'An approachable guide to the everyday decisions behind financial confidence—earning, saving, borrowing, and building a clearer relationship with money.'},
 {title:'Let Them Theory',author:'Mel Robbins',genre:'Self growth',color:'#db8267',height:342,width:60,mark:'LET',description:'A liberating invitation to stop spending energy on other people’s choices and refocus on what is actually yours to shape.'},
 {title:'Open',author:'Andre Agassi',genre:'Memoir',color:'#232323',height:330,width:55,mark:'OPEN',description:'A candid, high-intensity memoir about talent, pressure, identity, and finding a life beyond the expectations placed on you.'},
 {title:'The Shining',author:'Stephen King',genre:'Horror',color:'#b6372d',height:353,width:60,mark:'REDRUM',description:'A family takes on caretaking duties at an isolated mountain hotel, where a long winter begins to stir unsettling forces.'},
 {title:'It',author:'Stephen King',genre:'Horror',color:'#eee4cf',height:337,width:48,mark:'DERRY',description:'A group of childhood friends confronts a terrifying presence that has shadowed their town—and their memories—for years.'},
 {title:'David and Goliath',author:'Malcolm Gladwell',genre:'Ideas',color:'#4c735d',height:295,width:47,mark:'DAVID',description:'A fresh look at what can make apparent disadvantages unexpectedly powerful, and why familiar assumptions about strength can mislead us.'},
 {title:'The Tipping Point',author:'Malcolm Gladwell',genre:'Ideas',color:'#dfb337',height:322,width:52,mark:'POINT',description:'An exploration of the small shifts, distinctive people, and surprising conditions that can turn a quiet idea into a cultural wave.'},
 {title:'Outliers',author:'Malcolm Gladwell',genre:'Ideas',color:'#f0eee4',height:347,width:59,mark:'OUTLIERS',description:'A thoughtful challenge to the myth of solitary success, tracing the hidden opportunities, timing, and communities behind exceptional achievement.'},
 {title:'Atomic Habits',author:'James Clear',genre:'Self growth',color:'#d7b64e',height:307,width:48,mark:'1%',description:'A clear, encouraging framework for making tiny changes that compound, with attention to systems, identity, and the environment around you.'},
 {title:"Don’t Believe Everything You Think",author:'Joseph Nguyen',genre:'Mindfulness',color:'#604f93',height:338,width:57,mark:'THINK',description:'A gentle examination of overthinking and inner peace, inviting you to notice the stories your mind creates without becoming trapped inside them.'},
 {title:'Ikigai',author:'Francesc Miralles',genre:'Mindfulness',color:'#e27161',height:286,width:45,mark:'IKIGAI',description:'A reflective look at the Japanese idea of purpose and the everyday rituals that can make a long life feel meaningful and connected.'},
 {title:'The Alchemist',author:'Paulo Coelho',genre:'Fiction',color:'#b88b42',height:355,width:57,mark:'SOUL',description:'A luminous fable about a shepherd on an extraordinary journey, following a dream that asks him to listen to the world in new ways.'},
 {title:'The Mountain Is You',author:'Brianna Wiest',genre:'Self growth',color:'#6f8579',height:321,width:51,mark:'RISE',description:'A compassionate guide to recognizing self-sabotage and turning inner conflict into the raw material for lasting personal change.'},
 {title:'The Art of Letting Go',author:'Lucas Hayes',genre:'Self growth',color:'#bb866a',height:300,width:48,mark:'EASE',description:'A calming companion for releasing repetitive thought loops, making room for steadier attention, acceptance, and a quieter kind of strength.'},
 {title:'Dare to Succeed',author:'Success Center',genre:'Self growth',color:'#8a573f',height:315,width:52,mark:'DARE',description:'A treasury of inspirational ideas about focus, perseverance, meaningful contribution, and building a life with intention.'},
 {title:'The Body Keeps the Score',author:'Bessel van der Kolk',genre:'Health',color:'#5c9eae',height:340,width:54,mark:'TRAUMA',accent:true,spineClass:'body-keeps-score',coverISBN:'9780143127741',description:'A compassionate, research-grounded exploration of how trauma can shape the body and mind, and the pathways people use to heal and reconnect.'}
];
document.querySelector('#bookCount').textContent = books.length;
const shelf = document.querySelector('#shelfGrid'), chips = document.querySelector('#chips'), nav = document.querySelector('#genreNav');
const genres = ['All', ...new Set(books.map(b=>b.genre))]; let activeGenre='All', query='';
const esc = s => s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function renderFilters(){const controls=genres.map(g=>`<button class="${g===activeGenre?'active':''}" data-genre="${g}">${g}</button>`).join('');chips.innerHTML=controls;nav.innerHTML=controls;}
function renderShelf(){const displayed=books.filter(b=>(activeGenre==='All'||b.genre===activeGenre)&&`${b.title} ${b.author} ${b.genre}`.toLowerCase().includes(query)); shelf.innerHTML=displayed.map((b,i)=>`<button class="book ${b.accent?'accent':''} ${b.spineClass||''}" style="--book:${b.color};--height:${b.height}px;--width:${b.width}px;--font:${b.width>55?'15px':'13px'}" data-index="${books.indexOf(b)}" aria-label="Open ${esc(b.title)} by ${esc(b.author)}"><span class="spine-text"><span class="spine-author">${esc(b.author)}</span><span class="spine-title">${esc(b.title)}</span><span class="spine-mark">${b.mark}</span></span></button>`).join('');document.querySelector('#resultLabel').textContent=`${displayed.length} ${displayed.length===1?'book':'books'} to get lost in`;document.querySelector('#shelfEyebrow').textContent=activeGenre==='All'?'The complete shelf':activeGenre;}
function chooseGenre(g){activeGenre=g;query='';document.querySelector('#searchInput').value='';renderFilters();renderShelf();closeMenu();document.querySelector('#shelf').scrollIntoView({behavior:'smooth',block:'start'});}
document.addEventListener('click',e=>{const genre=e.target.dataset.genre;if(genre)chooseGenre(genre);const book=e.target.closest('.book');if(book)openBook(books[book.dataset.index]);});
document.querySelector('#searchInput').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();activeGenre='All';renderFilters();renderShelf();});
const dialog=document.querySelector('#bookDialog'),cover=document.querySelector('#dialogCover'),coverStatus=document.querySelector('#coverStatus');async function findCover(b){cover.hidden=true;cover.removeAttribute('src');cover.alt='';coverStatus.hidden=false;coverStatus.textContent='Finding cover…';const showCover=url=>{cover.src=url;cover.alt=`Cover of ${b.title} by ${b.author}`;cover.onload=()=>{cover.hidden=false;coverStatus.hidden=true};cover.onerror=()=>{cover.hidden=true;coverStatus.hidden=false;coverStatus.textContent='Cover unavailable'}};if(b.coverISBN){showCover(`https://covers.openlibrary.org/b/isbn/${b.coverISBN}-L.jpg`);return}try{const response=await fetch(`https://openlibrary.org/search.json?title=${encodeURIComponent(b.title)}&author=${encodeURIComponent(b.author)}&limit=8&fields=title,cover_i`);if(!response.ok)throw new Error();const data=await response.json();const normalized=s=>s.toLowerCase().replace(/[^a-z0-9]/g,'');const match=data.docs.find(item=>item.cover_i&&normalized(item.title)===normalized(b.title))||data.docs.find(item=>item.cover_i);if(!match?.cover_i)throw new Error();showCover(`https://covers.openlibrary.org/b/id/${match.cover_i}-L.jpg`)}catch{coverStatus.textContent='Cover unavailable'}}function renderFramework(book){document.querySelector('#investorFramework').innerHTML=book.framework?`<details class="investor-framework"><summary>Defensive investor framework <span>+</span></summary><div><p>Inspired by Graham’s three enduring ideas:</p><ol><li><strong>Automate DCA.</strong> A fixed contribution schedule reduces emotional market timing.</li><li><strong>Weigh the business.</strong> Separate price noise from earnings, book value, and balance-sheet strength.</li><li><strong>Demand a margin of safety.</strong> Consider candidates only at a meaningful discount to calculated value.</li></ol><a href="defensive_investor.py" download>Download the Python framework <span>↓</span></a><small>Educational illustration only — not investment advice.</small></div></details>`:''}function openBook(b){const spine=document.querySelector('#dialogSpine');spine.style.setProperty('--book',b.color);spine.dataset.title=b.title;document.querySelector('#dialogGenre').textContent=b.genre;document.querySelector('#dialogTitle').textContent=b.title;document.querySelector('#dialogAuthor').textContent=b.author;document.querySelector('#dialogDescription').textContent=b.description;renderFramework(b);dialog.showModal();findCover(b)}document.querySelector('#closeDialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
const menuButton=document.querySelector('#menuButton'),menu=document.querySelector('#menuPanel'),scrim=document.querySelector('#scrim');function closeMenu(){menu.classList.remove('open');scrim.classList.remove('visible');menuButton.setAttribute('aria-expanded','false');menu.setAttribute('aria-hidden','true');}menuButton.onclick=()=>{const open=!menu.classList.contains('open');menu.classList.toggle('open',open);scrim.classList.toggle('visible',open);menuButton.setAttribute('aria-expanded',open);menu.setAttribute('aria-hidden',!open)};scrim.onclick=closeMenu;
const phrase="Omari’s library";let char=0;const typer=document.querySelector('#typewriter');(function type(){if(char<phrase.length){typer.textContent+=phrase[char++];setTimeout(type,char===1?280:72)}})();
renderFilters();renderShelf();
document.documentElement.classList.add('library-js-ready');
